// 0.1离线交互原型。无网络请求、无账号登录、无真实数据提交。
const screens=JSON.parse(document.getElementById('screen-data').textContent);
const byId=Object.fromEntries(screens.map(s=>[s.id,s]));
const initial={screen:'home',draft:'airport\nluggage\ndelay',mode:'sample',count:20,month:'2026-10',answers:{},index:0,flags:{easy:false,error_prone:true,favorite:true,manual_needs_correction:false}};
let state={...initial,answers:{},flags:{...initial.flags}};let answersRevealed=false;
const bank=[['luggage','行李',['机场','行李','座位','车票']],['airport','机场',['机场','火车','司机','行李']],['delay','延迟',['座位','地图','延迟','车票']],['ticket','车票',['车票','学校','行李','天气']],['journey','旅程',['司机','旅程','机场','教室']],['travel','旅行',['阅读','睡觉','旅行','选择']],['flight','航班',['航班','时间','地图','街道']],['seat','座位',['飞机','座位','雨伞','车票']],['arrive','到达',['出发','离开','帮助','到达']],['depart','出发',['出发','等待','选择','记录']]];
let paper=[];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const el=document.getElementById('screen');
function navigate(id){if(!byId[id])return;state.screen=(id==='quiz'&&answersRevealed)?'quiz_results':id;render();document.getElementById('viewport').scrollTop=0;history.replaceState(null,'','#'+id);}
function btn(label,to,kind=''){return `<button class="${kind}" data-to="${to}">${esc(label)}</button>`;}
function render(){const s=byId[state.screen];document.getElementById('label').textContent=s.title;document.querySelectorAll('aside button').forEach(b=>b.classList.toggle('current',b.dataset.to===s.id));
 let cards=s.cards.map(c=>c.kind==='calendar'?calendar():`<button class="card ${c.kind}" ${c.to?`data-to="${c.to}"`:''}><strong>${esc(c.title)}</strong><span>${esc(c.body)}</span></button>`).join('');
 let foot=btn(s.primary,s.to,'primary')+`<div class="secondary">${s.secondary.map(a=>btn(a[0],a[1])).join('')}</div>`;
 if(s.id==='add')cards=`<label>单词或短语<textarea id="draft" rows="5">${esc(state.draft)}</textarea></label><p class="muted">按换行或逗号分隔；短语内空格保留。每批最多30项。</p><div class="card tint">主题：旅行<br>口音：美音 · 女声A</div>`,foot='<button class="primary" data-action="parse">解析并确认词义</button>';
 if(s.id==='confirm'){const words=state.draft.split(/[\n,，;；]+/).map(w=>w.trim()).filter(Boolean);cards=words.map((w,i)=>`<div class="card"><strong>${esc(w)}</strong><span>${bank.find(x=>x[0]===w)?.[1]||'演示词典无结果，请修改输入后重试'}</span>${bank.some(x=>x[0]===w)?'<label><input type="checkbox" checked> 确认此义项</label>':''}</div>`).join('');}
 if(s.id==='annotations'){cards=Object.entries({easy:'简单词',error_prone:'易错词',favorite:'收藏',manual_needs_correction:'待纠错'}).map(([k,v])=>`<label class="card"><strong>${v}</strong><input type="checkbox" data-flag="${k}" ${state.flags[k]?'checked':''}></label>`).join('')+'<p class="muted">简单与易错互斥；这里只修改演示状态。</p>';}
 if(s.id==='search')cards='<input id="query" placeholder="搜索英文或中文" value="luggage"><div id="search-results"></div>',setTimeout(search,0);
 if(s.id==='quiz_setup')cards=`<label>月份<input type="month" id="month" value="${state.month}" max="2026-10"></label><div class="card tint"><strong>演示题库10词</strong><span>实际产品使用所选月份学过的词。</span></div><label class="card"><input type="radio" name="mode" value="sample" ${state.mode==='sample'?'checked':''}> 抽样测试</label><label>题量<select id="count">${[10,20,30,50].map(x=>`<option ${state.count===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="card"><input type="radio" name="mode" value="full" ${state.mode==='full'?'checked':''}> 全量测试</label><p class="muted">本演示最多10题；选择大于题库数量时使用全部题目。</p>`,foot='<button class="primary" data-action="startQuiz">开始月测</button>';
 if(s.id==='quiz'){if(!paper.length)paper=bank.slice();const q=paper[state.index];cards=`<p class="muted">第 ${state.index+1} / ${paper.length} 题 · 答案仅存在本页内存</p><div class="card hero"><strong>${q[0]}</strong><span>选择中文释义</span></div>`+q[2].map((a,i)=>`<button class="card option ${state.answers[state.index]===a?'selected':''}" data-answer="${esc(a)}"><strong>${String.fromCharCode(65+i)}　${esc(a)}</strong></button>`).join('');foot=`<div class="secondary"><button data-action="prev">上一题</button><button data-action="next">下一题</button></div><button class="primary" data-to="quiz_submit">答题卡 / 交卷</button><button data-to="quiz_history">暂存退出（本页）</button>`;}
 if(s.id==='quiz_submit'){if(!paper.length)paper=bank.slice();const done=Object.keys(state.answers).length;cards=`<div class="card hero"><strong>已答 ${done} / ${paper.length}</strong><span>未答 ${paper.length-done} 题，确认交卷后按错误计分。</span></div><div class="answergrid">`+paper.map((q,i)=>`<button class="${state.answers[i]?'selected':''}" data-index="${i}">${i+1}</button>`).join('')+'</div>';foot='<button class="primary" data-action="submitQuiz">确认交卷并计分</button>'+btn('继续作答','quiz');}
 if(s.id==='quiz_score'&&answersRevealed){const right=paper.filter((q,i)=>state.answers[i]===q[1]).length,total=paper.length,score=right/total*100;const grade=score>=90?'优秀':score>=80?'良好':score>=60?'合格':'待加强';cards=`<div class="card hero"><strong>${score.toFixed(1)}分 · ${grade}</strong><span>答对 ${right} / ${total} · ${state.mode==='sample'?'抽样':'全量'}测试</span></div><div class="card tint">错题 ${total-right} 个已在演示结果中整理</div><p class="muted">原型不会写入真实错题集。正式系统交卷与错题归集须同事务提交。</p>`;}
 if(s.id==='quiz_results'&&answersRevealed)cards=paper.map((q,i)=>`<div class="card ${state.answers[i]===q[1]?'tint':''}"><strong>${q[0]} · ${state.answers[i]===q[1]?'正确':state.answers[i]?'回答错误':'未作答'}</strong><span>你的答案：${esc(state.answers[i]||'未答')}<br>正确答案：${q[1]}</span></div>`).join('');
 if(s.id==='quiz_history'&&paper.length&&!answersRevealed)cards='<div class="card tint"><strong>本页未完成测验</strong><span>已答'+Object.keys(state.answers).length+' / '+paper.length+'</span></div>'+btn('继续答题','quiz');
 if(s.id==='lookup')cards='<p>Our <button class="inline" data-lookup="luggage">luggage</button> arrived at the <button class="inline" data-lookup="airport">airport</button> after a short <button class="inline" data-lookup="delay">delay</button>.</p><div id="definition" class="card hero"><strong>luggage</strong><span>n. 行李（不可数）</span></div><p class="muted">正式产品所有英文词均可点选；本演示提供三个可点示例词。发音在原型中不联网合成。</p>';
 if(s.id==='share'||s.id==='share_words')foot='<button class="primary" data-action="poster">下载示例海报 SVG</button>'+btn('返回',s.id==='share'?'checkin':'words');
 if(s.id==='export_done')foot='<button class="primary" data-action="export">下载演示 CSV</button>'+btn('返回单词本','words');
 if(s.id==='correction')cards='<label>问题类型<select><option>释义</option><option>音标</option><option>例句</option><option>拼写</option></select></label><div class="card">当前内容：n. 行李</div><label>建议修正<textarea rows="4">行李（不可数名词）</textarea></label><p class="muted">家长提交，管理员确认应用；历史学习记录保留。</p>';
 el.innerHTML=`<div class="status">9:41 <span>•••　◉</span></div><div class="appbar"><button data-to="home">词伴</button><small>0.1</small></div><div class="content"><p class="eyebrow">${esc(s.id==='quiz'?state.month+'月测 · 演示试卷':s.sub)}</p><h1>${esc(s.title)}</h1>${cards}<div class="actions">${foot}</div></div><nav>${['今日','单词本','日历','我的'].map((t,i)=>btn(t,['home','words','calendar','family'][i],s.tab===t?'active':'')).join('')}</nav>`;
}
function calendar(){return '<div class="calendar">'+['一','二','三','四','五','六','日'].map(x=>'<span style="text-align:center">'+x+'</span>').join('')+'<span></span><span></span><span></span>'+Array.from({length:31},(_,i)=>`<button data-to="wrong" class="${i===15?'selected':''}">${i+1}${[12,13,14,15].includes(i)?'<small>✓</small>':''}</button>`).join('')+'</div>';}
function search(){const q=document.getElementById('query');if(!q)return;const found=bank.filter(x=>x[0].includes(q.value.trim().toLowerCase())||x[1].includes(q.value.trim()));document.getElementById('search-results').innerHTML=found.length?found.map(x=>`<button class="card" data-to="lookup"><strong>${x[0]}</strong><span>${x[1]}</span></button>`).join(''):'<p>演示词库中没有结果。正式系统将查询词典。</p>';}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u);}
document.addEventListener('input',e=>{if(e.target.id==='query')search();if(e.target.id==='draft')state.draft=e.target.value;});
document.addEventListener('change',e=>{if(e.target.dataset.flag){const k=e.target.dataset.flag;state.flags[k]=e.target.checked;if(e.target.checked&&k==='easy')state.flags.error_prone=false;if(e.target.checked&&k==='error_prone')state.flags.easy=false;render();}if(e.target.name==='mode')state.mode=e.target.value;if(e.target.id==='count')state.count=Number(e.target.value);if(e.target.id==='month')state.month=e.target.value;});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.to){navigate(b.dataset.to);return;}if(b.dataset.index!==undefined){state.index=Number(b.dataset.index);navigate('quiz');return;}
 if(b.dataset.answer){state.answers[state.index]=b.dataset.answer;render();return;}
 if(b.dataset.lookup){const q=bank.find(x=>x[0]===b.dataset.lookup);document.getElementById('definition').innerHTML='<strong>'+q[0]+'</strong><span>'+q[1]+'</span>';return;}
 switch(b.dataset.action){
 case 'parse':{const ws=state.draft.split(/[\n,，;；]+/).map(x=>x.trim()).filter(Boolean);if(!ws.length||ws.length>30){alert('请输入1–30个单词或短语。');return;}navigate('confirm');break;}
 case 'startQuiz':{if(!state.month||state.month>'2026-10'){alert('请选择不晚于演示当前月2026-10的月份。');return;}paper=bank.map(x=>({x,k:Math.random()})).sort((a,b)=>a.k-b.k).map(x=>x.x).slice(0,state.mode==='full'?bank.length:Math.min(state.count,bank.length));state.answers={};state.index=0;answersRevealed=false;navigate('quiz');break;}
 case 'prev':state.index=Math.max(0,state.index-1);render();break;
 case 'next':if(state.index===paper.length-1)navigate('quiz_submit');else {state.index++;render();}break;
 case 'submitQuiz':answersRevealed=true;navigate('quiz_score');break;
 case 'export':download('wordmate-demo.csv','\uFEFFword,meaning\r\n'+bank.slice(0,3).map(q=>q[0]+','+q[1]).join('\r\n'),'text/csv;charset=utf-8');break;
 case 'poster':download('wordmate-demo-poster.svg','<svg xmlns="http://www.w3.org/2000/svg" width="600" height="800"><rect width="600" height="800" fill="#f7f8f2"/><text x="60" y="150" fill="#255d48" font-size="40">词伴 · 今天也在进步</text><text x="60" y="300" fill="#255d48" font-size="30">'+(state.screen==='share'?'今日学习10词 · 连续5天':'airport · luggage · delay')+'</text><text x="60" y="700" font-size="18">离线原型示例，不是真实学习记录</text></svg>','image/svg+xml');break;
 }
});
document.getElementById('reset').onclick=()=>{state={...initial,answers:{},flags:{...initial.flags}};paper=[];answersRevealed=false;navigate('home');};
document.querySelector('aside').innerHTML=screens.map((s,i)=>btn(String(i+1).padStart(2,'0')+' '+s.title,s.id)).join('');
navigate(byId[location.hash.slice(1)]?location.hash.slice(1):'home');
